ario":"ELO-00055","cadastro_concluido_em":"2026-05-30T13:03:02.422Z","nome":"Andrielle Aparecida Testoni","nome_preferido":"Andrielle","tipo":"Pessoa","telefone":"47984265908","email":"agenciaazunni@gmail.com","instagram":"@azzuniagencia","linkedin":null,"site":null,"empresa":"Azzuni","cargo":"Fundador","descricao_negocio":"A Azzuni resolve problemas de geração de demanda, captação de clientes, atendimento comercial e crescimento empresarial. Oferecemos tráfego pago, automação de atendimento com Inteligência Artificial, agentes SDR, agentes de vendas com IA, funis de vendas, qualificação automática de leads, integração com WhatsApp, automação comercial e estratégias de conversão. Nosso objetivo é transformar visitantes em leads qualificados, reduzir o tempo de resposta e aumentar as vendas através de tecnologia, automação e inteligência artificial.","setor":"Tecnologia","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"1-5 anos","interesse_ministerio":"Crescimento espiritual","temas_connect":"Marketing","conhecimentos_compartilhar":"Marketing e Vendas, IA para negócios","disposto_mentor":true,"igreja_comunidade":"Sim, Permanecer Church","escola_servos":"Não","contribuir_palestras_workshops":true,"impacto_reino":"Acreditamos que podemos impactar o Reino de Deus servindo pessoas e empresas com excelência, integridade e propósito. Ao ajudar negócios a crescerem de forma saudável através da tecnologia e da inovação, contribuímos para gerar oportunidades, prosperidade e transformação na vida das pessoas.","desafios_empreendedor":"Tempo","origem_connect":"No Culto","contatos_publicos_origem":"@azzuniagencia","pendencias_validacao":null,"linha_origem_mantida":450,"linhas_origem_consolidadas":"450","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00056","cadastro_concluido_em":"2026-05-30T09:40:56.242Z","nome":"Natalia Idemori","nome_preferido":"Natal