sponsabilidade. Entendo meu trabalho como uma forma de ajudar, elevar e abençoar pessoas através daquilo que faço todos os dias.","desafios_empreendedor":"omo estou iniciando meu negócio, um dos meus maiores desafios tem sido vencer a timidez, perder a vergonha de fazer networking e me tornar mais sociável para criar conexões, parcerias e oportunidades.","origem_connect":"Através da divulgação da PERMANECER","contatos_publicos_origem":"Meu instagram: @nicolethaina_ Minha loja da Shopee: NT Decor / https://br.shp.ee/ENL7TqC WhatsApp: 47 99961-1529","pendencias_validacao":null,"linha_origem_mantida":412,"linhas_origem_consolidadas":"412","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00092","cadastro_concluido_em":"2025-11-23T22:54:18.571Z","nome":"Josiane Marilyn Eichstaed","nome_preferido":"Josi","tipo":"Pessoa","telefone":"47997853506","email":"clinicajme@gmail.com","instagram":null,"linkedin":null,"site":null,"empresa":"JME Clínica de Fisioterapia","cargo":"Ceo","descricao_negocio":"Aliviar dores Prestamos serviços de fisioterapia, quiropraxia, massagens, pilates, yoga, nutricionista","setor":"Saúde","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"mais de 10 anos","interesse_ministerio":"Todos itens acima","temas_connect":"Todos itens acima","conhecimentos_compartilhar":"Saúde","disposto_mentor":true,"igreja_comunidade":"Sim, Permanecer Church","escola_servos":"Não","contribuir_palestras_workshops":true,"impacto_reino":"Podendo aliviar as dores das pessoas tanto emocionais como físicas","desafios_empreendedor":"Formar uma família, onde eu possa ajudar o maior número de pessoas","origem_connect":"Frequentando os cultos","contatos_publicos_origem":"Clínica dra Josiane eichstaedt","pendencias_validacao":null,"linha_origem_mantida":411,"linhas_origem_consolidadas":"411","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00093","