faturamento saudável pro crescimento da empresa","origem_connect":"Indicação","contatos_publicos_origem":"Instagram @studiombsarq","pendencias_validacao":null,"linha_origem_mantida":357,"linhas_origem_consolidadas":"357","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00143","cadastro_concluido_em":"2025-07-24T00:20:35.870Z","nome":"Lino William Nardelli Heymanns","nome_preferido":"Lino","tipo":"Pessoa","telefone":"4799490816","email":"linownardelli@hotmail.com","instagram":"@drlinonardelli; @drapamelaagostinho; @cristalodontobnu","linkedin":null,"site":null,"empresa":"Cristal Odontologia Especializada","cargo":"CEO","descricao_negocio":"Na Cristal Odontologia, resolvemos um dos problemas mais comuns e impactantes da vida das pessoas: a dor de dente, o desconforto ao sorrir e a insegurança com a própria imagem, desde a infância até a fase adulta. Oferecemos tratamentos especializados que vão desde o alívio imediato da dor (como tratamentos de canal e cirurgias) até a reabilitação completa do sorriso com implantes, próteses e aparelhos ortodônticos — incluindo tecnologias modernas como Invisalign. Cuidamos com carinho especial das crianças, pois sabemos que um atendimento humanizado desde cedo é fundamental para criar hábitos saudáveis, prevenir traumas e garantir sorrisos confiantes para a vida toda. Nosso propósito é devolver a saúde, a autoestima e a confiança dos nossos pacientes, com um atendimento humano, ético e altamente qualificado.","setor":"Serviços de saúde","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"1-5 anos","interesse_ministerio":"Crescimento espiritual/Networking","temas_connect":"Gestao, inovação e marketing","conhecimentos_compartilhar":"Tecnologia, Recursos Humanos","disposto_mentor":true,"igreja_comunidade":"Sim, Permanecer Church","escola_servos":"Sim","contribuir_palestras_workshops":true,"impacto_reino":"Nosso negócio impacta o Reino de Deus ao cuidar da saúde e do bem-estar das pessoas com amor, integridade e respeito, valores que refletem os princípios cristãos. Através do atendimento humanizado e do compromisso com a excelência, buscamos não só transformar sorrisos, mas também tocar vidas, oferecendo conforto, esperança e confiança para que cada paciente viva com mais dignidade e alegria. Além disso, ao atuar com ética e responsabilidade, servimos como exemplo no mercado, inspirando outros profissionais e a comunidade a praticarem o cuidado genuíno e a solidariedade, frutos do Reino de Deus em ação na sociedade.","desafios_empreendedor":"Gestão dos negócios e marketing","origem_connect":"Pela igreja","contatos_publicos_origem":"@drlinonardelli @drapamelaagostinho @cristalodontobnu","pendencias_validacao":null,"linha_origem_mantida":356,"linhas_origem_consolidadas":"31, 356","registros_descartados":1}},{"chave_importacao_formulario":"ELO-00144","cadastro_concluido_em":"2025-07-23T19:17:24.025Z","nome":"Rafael Rizzotto","nome_preferido":"Rafael","tipo":"Pessoa","telefone":"47999514173","email":"agilbnu@gmail.com","instagram":"@agilbnu","linkedin":null,"site":null,"empresa":"Ágil Pinturas","cargo":"Diretor","descricao_negocio":"Pintura Industrial, Predial, Comercial e Residencial, pintura de máquinas industriais, pintura de pisos em epóxi","setor":"Serviços","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"mais de 10 anos","interesse_ministerio":"Todos","temas_connect":"Todos","conhecimentos_compartilhar":"Gestão de negócios, Acompanhamento de obras","disposto_mentor":true,"igreja_comunidade":"Sim, Permanecer Church","escola_servos":"Não","contribuir_palestras_workshops":true,"impacto_reino":"Colaborando com o crescimento","desafios_empreendedor":"Encontrar mão de obra qualificada para contratação","origem_connect":"Permanecer Church","contatos_publicos_origem":"@ag