nect":"Inovação ética crista nos negócios,","conhecimentos_compartilhar":"Gestão de negócios","disposto_mentor":true,"igreja_comunidade":"Shalom","escola_servos":"Frequento outra igreja","contribuir_palestras_workshops":true,"impacto_reino":"Nada quebrado nada fora do lugar","desafios_empreendedor":"Luas 1: 37","origem_connect":"No Uber","contatos_publicos_origem":"No whatsapp","pendencias_validacao":null,"linha_origem_mantida":309,"linhas_origem_consolidadas":"309","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00181","cadastro_concluido_em":"2025-05-26T11:50:29.311Z","nome":"Ágatha Samy Borba Carniel","nome_preferido":"Ágatha","tipo":"Pessoa","telefone":"47992656780","email":"agathasamyborba@gmail.com","instagram":"@mandatocultural.mkt","linkedin":null,"site":null,"empresa":"Mandato Cultural MKT","cargo":"CEO","descricao_negocio":"A Mandato Cultural não é só um nome bonito. É um chamado. Na Bíblia, Mandato Cultural é a ordem que Deus deu aos seres humanos para cuidar da criação, desenvolver, transformar e exercer domínio responsável sobre a Terra. Isso significa multiplicar, organizar, gerar valor, construir, comunicar e fazer tudo isso com excelência, ética e amor — para o bem das pessoas e para a glória de Deus. E se o Mandato Cultural se aplica à vida, ele também se aplica ao trabalho. Eu entendo o marketing como uma ferramenta de transformação: uma forma de potencializar aquilo que é bom, dar voz a quem gera valor e construir pontes reais entre marcas e pessoas. Por isso, a Mandato Cultural nasceu. Para servir empreendedores, profissionais e empresas que querem comunicar com propósito, alinhando sua identidade, seus valores e sua missão ao que mostram ao mundo. Aqui, marketing não é só sobre vender. É sobre cultivar, cuidar, comunicar com verdade e gerar impacto positivo na cultura e na sociedade. É sobre entender que cada negócio tem um papel no mundo — e que comunicar bem faz parte desse chamado. Se Deus me chama a agir e a servir… cá estamos nós. 💛","setor":"Marketing","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"1-5 anos","interesse_ministerio":"Mentoria/Liderança/Espiritual","temas_connect":"Gestão, Inovação, Ética Cristã nos Negócios/Como evangelizar clientes?","conhecimentos_compartilhar":"Marketing e Vendas, Recursos Humanos","disposto_mentor":true,"igreja_comunidade":"Sim, Primeira Igreja Batista Pioneira de Blumenau","escola_servos":"Frequento outra igreja","contribuir_palestras_workshops":true,"impacto_reino":"Para servir empreendedores, profissionais e empresas que querem comunicar com propósito, alinhando sua identidade, seus valores e sua missão ao que mostram ao mundo.","desafios_empreendedor":"Precificação de serviço","origem_connect":"Através de um membro","contatos_publicos_origem":"Instagram: @mandatocultural.mkt Threads: mandatocultural.mkt Facebook: Mandato Cultural MKT WhatsApp: (47) 99265-6780","pendencias_validacao":null,"linha_origem_mantida":308,"linhas_origem_consolidadas":"308","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00182","cadastro_concluido_em":"2025-05-26T00:06:25.682Z","nome":"Josemar Luiz da Luz","nome_preferido":"Luiz","tipo":"Pessoa","telefone":"47991571147","email":"luizz_bnu@hotmail.com","instagram":null,"linkedin":null,"site":null,"empresa":"IHM Soluções Elétricas","cargo":"Dono","descricao_negocio":"Soluções Elétricas Residenciais, prediais e industrial","setor":"Serviços","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"mais de 10 anos","interesse_ministerio":"Networking, Mentoria, Crescimento Espiritual","temas_connect":"Finanças, Cristã nos negócios","conhecimentos_compartilhar":"ELÉTRICA","disposto_mentor":false,"igreja_comunidade":"Sim, Permanecer Church","escola_servos":"Não","contribuir_palestras_workshops":false