s: serviço especializado para aliviar o desconforto e prevenir futuras encravadas. Tratamento de Fungos: protocolo específico para combater fungos nas unhas e restaurar a aparência saudável das mesmas.","setor":"Serviços de alto cuidados e saudes dos pés podologa e spa dos pés e mãos.","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"Menos de 1 ano","interesse_ministerio":"Crescimento, novas propostas e oportunidades, e conhecimentos","temas_connect":"Todos ...","conhecimentos_compartilhar":"Conhecimentos na ares de Spa e plásticas dos pés e pedal","disposto_mentor":true,"igreja_comunidade":"Quinzenal","escola_servos":null,"contribuir_palestras_workshops":true,"impacto_reino":"Sim","desafios_empreendedor":"E Ter o conhecimento e o aleitamento da área podal e spa dos pés e ter a confiança das pessoas para os procedimentos","origem_connect":"Uma grande amiga que ja frenguenta me convidou para visitar.","contatos_publicos_origem":"instagram: emillymakeupp2024 WhatsApp: 47 991797171","pendencias_validacao":null,"linha_origem_mantida":165,"linhas_origem_consolidadas":"165","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00307","cadastro_concluido_em":"2024-11-04T13:46:23.647Z","nome":"Rafael Matias Ventura","nome_preferido":"Rafa","tipo":"Pessoa","telefone":"47991278988","email":"rventura.comercial@gmail.com","instagram":"@rafamventura","linkedin":null,"site":null,"empresa":"Rede Animal Farma, Pet Liebe, Casarão dos Sonhos e Ventura Soluções Empresariais","cargo":"Diretor de Negócios, Administrador e Consultor","descricao_negocio":"São 5 operações. Franqueadora, franquia fármaco Vet, clínica veterinária, venda de colchões e demais produtos terapêuticos e escritório de consultoria","setor":"Saúde veterinária, Franshising, Qualidade de vida e Consultoria Empresarial","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber