 e estilo, maternidade","disposto_mentor":true,"igreja_comunidade":"Mensal","escola_servos":null,"contribuir_palestras_workshops":true,"impacto_reino":"Revelando o poder materno para a mãe para que possa compreender que ela tem o poder de mudar a próxima geração e ela entendendo que o seu maior papel é conduzir seus filhos ao reino.","desafios_empreendedor":"Vendas e tempo","origem_connect":"Através de uma amiga","contatos_publicos_origem":null,"pendencias_validacao":"Telefone precisa de validação","linha_origem_mantida":121,"linhas_origem_consolidadas":"121","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00339","cadastro_concluido_em":"2024-09-23T22:30:17.124Z","nome":"Paulo Flores","nome_preferido":"Paulo Flores","tipo":"Pessoa","telefone":"47988990783","email":"reporterpauloflores@gmail.com","instagram":null,"linkedin":null,"site":null,"empresa":"89 FM","cargo":"Funcionário","descricao_negocio":"Sou radialista e vendedor de anúncios em radio","setor":"Comunicação e vendas","cidade":"Blumenau","estado":"SC","status":"aprovado","perfil_ativo":true,"receber_atualizacoes":true,"respostas_formulario":{"tempo_atuacao_empreendedorismo":"mais de 10 anos","interesse_ministerio":"Todos acima","temas_connect":"Todos acima","conhecimentos_compartilhar":"Marketing e Vendas","disposto_mentor":false,"igreja_comunidade":"Quinzenal","escola_servos":null,"contribuir_palestras_workshops":false,"impacto_reino":"Sim","desafios_empreendedor":"Entender minha capacidade de empreender","origem_connect":"Amigo","contatos_publicos_origem":null,"pendencias_validacao":null,"linha_origem_mantida":120,"linhas_origem_consolidadas":"120","registros_descartados":0}},{"chave_importacao_formulario":"ELO-00340","cadastro_concluido_em":"2024-09-23T22:06:48.928Z","nome":"Cíntia dos Santos Silvério","nome_preferido":"Cíntia","tipo":"Pessoa","telefone":"47991814865","email":"cyntyadossantos@gmail.com","instagram":null,"linkedin":null,"site":null,"empresa":"RCV Elétrica e Ar Condicionado