categoria_nome":"Serviços","categoria_aliases":[],"cidade":"Blumenau","estado":"SC","origem_carga":"formulario_connect_sanitizado"},{"chave_importacao_formulario":"ELO-00063","nome":"Realizo procedimentos estéticos para melhorar a autoestima das pessoas","descricao":"Realizo procedimentos estéticos para melhorar a autoestima das pessoas","problemas_resolvidos":null,"especialidades":[],"categoria_nome":"Saúde","categoria_aliases":[],"cidade":"Blumenau","estado":"SC","origem_carga":"formulario_connect_sanitizado"},{"chave_importacao_formulario":"ELO-00014","nome":"Ajudo mulheres a voltarem pra casa","descricao":"Ajudo mulheres a voltarem pra casa, habitar em seu lar interno novamente.","problemas_resolvidos":"Ajudo mulheres a voltarem pra casa, habitar em seu lar interno novamente.","especialidades":[],"categoria_nome":"Saúde","categoria_aliases":[],"cidade":"Blumenau","estado":"SC","origem_carga":"formulario_connect_sanitizado"},{"chave_importacao_formulario":"ELO-00247","nome":"Serviço Educacional","descricao":"Qualificação de mão de obra.\nNa Jumper qualificamos criança e jovem na área da tecnologia, gestão e inglês\nNa Uninter qualificação de adultos com graduação, pós graduação e cursos técnicos.","problemas_resolvidos":null,"especialidades":["Qualificação de mão de obra.","Na Jumper qualificamos criança e jovem na área da tecnologia, gestão e inglês","Na Uninter qualificação de adultos com graduação, pós graduação e cursos técnicos."],"categoria_nome":"Serviço Educacional","categoria_aliases":[],"cidade":"Blumenau","estado":"SC","origem_carga":"formulario_connect_sanitizado"},{"chave_importacao_formulario":"ELO-00287","nome":"buscar indenizações para as vítimas de qualquer tipo de acidente, e temos vários diferenciais…","descricao":"Somos especializados em buscar indenizações para as vítimas de qualquer tipo de acidente, e temos vários diferenciais visando que a vítima não tenha preocupação além da sua saúde e recuperação.","problemas_resolvidos":null,"especiali